import React, { useState, useEffect } from "react";
import { motion, AnimatePresence } from "framer-motion";
import WorkerSplash from "./components/WorkerSplash";
import WorkerSignIn from "./components/SignIn";

function App() {
  const [status, setStatus] = useState("loading"); // loading -> ready -> dashboard

  // The "Elite" Cubic Bezier for Apple-style movement
  const vancouverEase = [0.16, 1, 0.3, 1];

  return (
    <div className="relative h-screen w-full bg-[#FFF24D] overflow-hidden">

      {/* LAYER 1: THE SIGN-IN (Always waiting underneath) */}
      <div className="absolute inset-0 z-10">
        {status !== "loading" && (
          <motion.div
            initial={{ opacity: 0, scale: 0.9, filter: "blur(10px)" }}
            animate={{ opacity: 1, scale: 1, filter: "blur(0px)" }}
            transition={{ duration: 1, ease: vancouverEase }}
          >
            <WorkerSignIn onLogin={() => setStatus("dashboard")} />
          </motion.div>
        )}
      </div>

      {/* LAYER 2: THE SPLASH (Sliding 'Steel Door' Effect) */}
      <AnimatePresence>
        {status === "loading" && (
          <motion.div
            key="splash-screen"
            initial={{ x: 0 }}
            exit={{ 
              x: "-100%", 
              skewX: [0, -10, 0], // Subtle "pull" effect as it slides
            }}
            transition={{ 
              duration: 1.2, 
              ease: [0.87, 0, 0.13, 1] // Heavy industrial slide
            }}
            className="absolute inset-0 z-50 bg-[#003366] flex items-center justify-center"
          >
            <WorkerSplash onComplete={() => setStatus("ready")} />
          </motion.div>
        )}
      </AnimatePresence>

      {/* LAYER 3: DASHBOARD OVERLAY */}
      {status === "dashboard" && (
        <motion.div 
          initial={{ opacity: 0 }} 
          animate={{ opacity: 1 }} 
          className="absolute inset-0 z-[100] bg-[#FFF24D]"
        >
          <div className="p-20 text-[#47510B] font-black italic text-6xl">
            DASHBOARD_LOADED
          </div>
        </motion.div>
      )}
    </div>
  );
}

export default App;
